import pathlib
import sys

from json_config.api import (
    ConfigLayer,
    ConfigLayerManager,
    ConfigValues,
    LayeredConfig,
)
from PySide6 import QtWidgets

# Generated by `make qrc`
import json_config_qt.resources.resources_rc  # noqa: F401
from json_config_qt.editor_dialog import ConfigEditorDialog


class _EmptyValues(ConfigValues):
    """Values class with no fields, for editing layers without a schema."""

    pass


class _FileConfig(LayeredConfig[_EmptyValues]):
    """Config used by the standalone launcher."""

    VALUES_CLASS = _EmptyValues
    NAME = "json_config_qt"


def config_from_files(paths: list[pathlib.Path]) -> LayeredConfig:
    """Build a config whose layers are *paths*; each overrides the previous one."""
    ConfigLayerManager.clear()
    manager = ConfigLayerManager(_FileConfig.NAME)
    previous: str | None = None
    for path in paths:
        layer = ConfigLayer(
            name=path.stem,
            depends_on=[previous] if previous else [],
            file_path=path,
        )
        manager.register(layer)
        previous = layer.name
    manager.load_all()
    return _FileConfig(layer_manager=manager)


def main() -> int:
    """Run the standalone editor on the layer files given on the command line.

    Returns:
        int: The application exit code.
    """
    app = QtWidgets.QApplication(sys.argv)
    paths = [pathlib.Path(arg) for arg in sys.argv[1:]]
    dialog = ConfigEditorDialog(config_from_files(paths))
    dialog.show()
    return app.exec()


if __name__ == "__main__":
    sys.exit(main())
